package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen1Test {

    private KeyedObjects2D dataset;
    private final Comparable col1 = "Column1";
    private final Comparable col2 = "Column2";
    private final Comparable row1 = "Row1";
    private final Comparable row2 = "Row2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_Success() {
        // Arrange: Populate dataset with data
        dataset.addObject("Value1", row1, col1);
        dataset.addObject("Value2", row1, col2);
        dataset.addObject("Value3", row2, col1);
        dataset.addObject("Value4", row2, col2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Value1", dataset.getObject(row1, col1));

        // Act
        dataset.removeColumn(col1);

        // Assert
        // 1. Column key should be removed from columnKeys list
        List columnKeys = dataset.getColumnKeys();
        assertEquals(1, columnKeys.size());
        assertEquals(col2, columnKeys.get(0));

        // 2. Column count should decrease
        assertEquals(1, dataset.getColumnCount());

        // 3. Data associated with the column should be removed from rows
        assertNull("Value for col1 should be null after removal", dataset.getObject(row1, col1));
        assertEquals("Value2", dataset.getObject(row1, col2));
        assertEquals("Value4", dataset.getObject(row2, col2));
        assertNull("Value for col1 (row2) should be null", dataset.getObject(row2, col1));
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKey_ThrowsException() {
        // Arrange: Add some data so the dataset isn't empty
        dataset.addObject("Value1", row1, col1);

        // Act: Attempt to remove a key that doesn't exist
        dataset.removeColumn("NonExistentKey");
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Act: Remove column from empty dataset
        // Since getColumnIndex will return -1, it should throw UnknownKeyException
        try {
            dataset.removeColumn(col1);
        } catch (UnknownKeyException e) {
            assertTrue(e.getMessage().contains("not recognised"));
        }
    }

    @Test
    public void testRemoveColumn_SingleColumn() {
        // Arrange
        dataset.addObject("Value1", row1, col1);

        // Act
        dataset.removeColumn(col1);

        // Assert
        assertEquals(0, dataset.getColumnCount());
        assertNull(dataset.getObject(row1, col1));
    }

    @Test
    public void testRemoveColumn_RowsWithNoDataForColumn() {
        // Arrange: Add a row that doesn't have the specific column key
        dataset.addObject("Value1", row1, col2);
        dataset.addObject("Value2", row2, col2);

        // Act: Remove col1 (which exists in columnKeys but rows don't have it)
        // Note: In most implementations of KeyedObjects2D, columnKeys is updated 
        // based on addObject calls. If col1 was never added, it triggers UnknownKeyException.
        // If col1 was added via a mechanism that doesn't add to rows, it tests the iterator loop.

        // To ensure col1 is in columnKeys but rows don't have it, we'd need internal access, 
        // but based on provided methods, we can only add via addObject.
        // So we test the standard flow.
        dataset.addObject("Value3", row1, col1);
        dataset.removeColumn(col1);

        assertEquals(1, dataset.getColumnCount());
        assertEquals(col2, dataset.getColumnKey(0));
    }
}
